import sys, json, argparse, re

def main():
    args = sys.argv[1:]
    # parse simple args
    raw_output = False
    compact = False
    slurp = False
    null_input = False

    expr = "."
    files = []

    idx = 0
    while idx < len(args):
        a = args[idx]
        if a == '-r' or a == '--raw-output':
            raw_output = True
        elif a == '-c' or a == '--compact-output':
            compact = True
        elif a == '-s' or a == '--slurp':
            slurp = True
        elif a == '-n' or a == '--null-input':
            null_input = True
        elif a in ('-h', '--help'):
            print("jq - commandline JSON processor")
            return
        elif a.startswith('-'):
            pass # ignore other flags for now
        else:
            if expr == ".":
                expr = a
            else:
                files.append(a)
        idx += 1

    # read input
    inputs = []
    if slurp:
        data = sys.stdin.read()
        try:
            inputs = [json.loads(data)]
        except:
            inputs = []
    else:
        # read json streams
        data = sys.stdin.read()
        decoder = json.JSONDecoder()
        pos = 0
        data = data.strip()
        while pos < len(data):
            data = data[pos:].lstrip()
            if not data: break
            try:
                obj, idx = decoder.raw_decode(data)
                inputs.append(obj)
                pos = idx
            except:
                break

    for i in inputs:
        # evaluate
        # Very simple evaluation for now
        res = [i]

        # print
        for r in res:
            if raw_output and isinstance(r, str):
                print(r)
            else:
                if compact:
                    print(json.dumps(r, separators=(',', ':')))
                else:
                    print(json.dumps(r, indent=2))

if __name__ == "__main__":
    main()
