import re

def tokenize(expr):
    tokens = []
    pattern = re.compile(r'\s+|(\.)|(\[)|(\])|(\{)|(\})|(\:)|(\,)|(\|)|(\()|(\))|(\+)|(\-)|(\*)|(\/)|(==)|(!=)|(>=)|(<=)|(>)|(<)|(true|false|null)|(\d+(?:\.\d+)?(?:[eE][+-]?\d+)?)|("[^"]*")|([a-zA-Z_][a-zA-Z0-9_]*)')
    pos = 0
    while pos < len(expr):
        match = pattern.match(expr, pos)
        if not match:
            raise Exception(f"Syntax error at: {expr[pos:]}")
        pos = match.end()
        if not match.group(0).isspace():
            tokens.append(match.group(0))
    return tokens

class Parser:
    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0

    def peek(self):
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return None

    def consume(self, expected=None):
        if expected:
            if self.peek() == expected:
                self.pos += 1
                return True
            return False
        else:
            t = self.peek()
            self.pos += 1
            return t

    def parse(self):
        return self.parse_expr()

    def parse_expr(self):
        # A simple recursive descent parser
        left = self.parse_term()
        while self.consume('|'):
            right = self.parse_term()
            left = {"type": "pipe", "left": left, "right": right}
        return left

    def parse_term(self):
        t = self.peek()
        if t == '.':
            self.consume('.')
            nxt = self.peek()
            if nxt and re.match(r'[a-zA-Z_]', nxt):
                field = self.consume()
                return {"type": "field", "field": field}
            elif nxt == '[':
                self.consume('[')
                if self.peek() == ']':
                    self.consume(']')
                    return {"type": "iterator"}
                else:
                    idx = self.parse_expr()
                    self.consume(']')
                    return {"type": "index", "index": idx}
            return {"type": "identity"}
        elif t and re.match(r'[a-zA-Z_]', t):
            func = self.consume()
            if func == 'map':
                self.consume('(')
                expr = self.parse_expr()
                self.consume(')')
                return {"type": "map", "expr": expr}
            elif func == 'select':
                self.consume('(')
                expr = self.parse_expr()
                self.consume(')')
                return {"type": "select", "expr": expr}
            elif func == 'keys':
                return {"type": "keys"}
            elif func == 'length':
                return {"type": "length"}
            else:
                return {"type": "func", "name": func}
        elif t == '[':
            self.consume('[')
            if self.peek() == ']':
                self.consume(']')
                return {"type": "array", "expr": None}
            expr = self.parse_expr()
            self.consume(']')
            return {"type": "array", "expr": expr}
        else:
            # literal or something
            val = self.consume()
            return {"type": "literal", "value": val}

def compile_ast(ast):
    if ast["type"] == "identity":
        return lambda x: [x]
    elif ast["type"] == "field":
        field = ast["field"]
        return lambda x: [x.get(field)] if isinstance(x, dict) else [None]
    elif ast["type"] == "pipe":
        left = compile_ast(ast["left"])
        right = compile_ast(ast["right"])
        return lambda x: [y for l in left(x) for y in right(l)]
    elif ast["type"] == "iterator":
        return lambda x: list(x.values()) if isinstance(x, dict) else list(x) if isinstance(x, list) else []
    elif ast["type"] == "index":
        # Simplified: string index or int index
        idx_ast = ast["index"]
        if idx_ast["type"] == "literal":
            val = idx_ast["value"]
            if val.startswith('"'):
                key = val.strip('"')
                return lambda x: [x.get(key)] if isinstance(x, dict) else [None]
            elif val.isdigit():
                i = int(val)
                return lambda x: [x[i]] if isinstance(x, list) and i < len(x) else [None]
        return lambda x: [None]
    elif ast["type"] == "map":
        expr = compile_ast(ast["expr"])
        return lambda x: [[y for item in x for y in expr(item)]] if isinstance(x, list) else [None]
    elif ast["type"] == "keys":
        return lambda x: [sorted(list(x.keys()))] if isinstance(x, dict) else [[i for i in range(len(x))]] if isinstance(x, list) else [None]
    elif ast["type"] == "length":
        return lambda x: [len(x)] if isinstance(x, (dict, list, str)) else [None]
    else:
        return lambda x: [None]

def evaluate(expr, data):
    tokens = tokenize(expr)
    parser = Parser(tokens)
    ast = parser.parse()
    compiled = compile_ast(ast)
    return compiled(data)

print(evaluate('.foo | .bar', {"foo": {"bar": 123}}))
print(evaluate('.[]', [1, 2, 3]))
print(evaluate('map(.foo)', [{"foo": 1}, {"foo": 2}]))
