import sys, json, re, argparse

def tokenize(expr):
    tokens = []
    pattern = re.compile(
        r'\s+|'
        r'(\.\.)|'
        r'(\.)|'
        r'(\[)|(\])|(\{)|(\})|(\:)|(\,)|(\|)|(\()|(\))|'
        r'(\+)|(\-)|(\*)|(\/)|(==)|(!=)|(>=)|(<=)|(>)|(<)|'
        r'(true|false|null)|'
        r'(\d+(?:\.\d+)?(?:[eE][+-]?\d+)?)|'
        r'("[^"]*")|'
        r'([a-zA-Z_][a-zA-Z0-9_]*)'
    )
    pos = 0
    while pos < len(expr):
        match = pattern.match(expr, pos)
        if not match:
            # just read one char
            tokens.append(expr[pos])
            pos += 1
            continue
        pos = match.end()
        if not match.group(0).isspace():
            tokens.append(match.group(0))
    return tokens

class Parser:
    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0

    def peek(self):
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return None

    def consume(self, expected=None):
        if expected:
            if self.peek() == expected:
                self.pos += 1
                return True
            return False
        else:
            t = self.peek()
            self.pos += 1
            return t

    def parse(self):
        if not self.tokens:
            return {"type": "identity"}
        return self.parse_expr()

    def parse_expr(self):
        left = self.parse_pipe()
        while self.consume(','):
            right = self.parse_pipe()
            left = {"type": "comma", "left": left, "right": right}
        return left

    def parse_pipe(self):
        left = self.parse_term()
        while self.consume('|'):
            right = self.parse_term()
            left = {"type": "pipe", "left": left, "right": right}
        return left

    def parse_term(self):
        t = self.peek()
        if t == '.':
            self.consume('.')
            nxt = self.peek()
            if nxt and re.match(r'[a-zA-Z_]', nxt) and nxt not in ('true', 'false', 'null'):
                field = self.consume()
                base = {"type": "field", "field": field}
            elif nxt == '"':
                # ."foo"
                pass # simplification
                base = {"type": "identity"}
            elif nxt == '[':
                self.consume('[')
                if self.peek() == ']':
                    self.consume(']')
                    base = {"type": "iterator"}
                else:
                    idx = self.parse_expr()
                    self.consume(']')
                    base = {"type": "index", "index": idx}
            else:
                base = {"type": "identity"}

            # handle chains like .foo.bar or .foo[0]
            while True:
                nxt = self.peek()
                if nxt == '.':
                    self.consume('.')
                    nnxt = self.peek()
                    if nnxt and re.match(r'[a-zA-Z_]', nnxt):
                        f = self.consume()
                        base = {"type": "pipe", "left": base, "right": {"type": "field", "field": f}}
                    else:
                        break
                elif nxt == '[':
                    self.consume('[')
