        return self.parse_expr()

    def parse_expr(self):
        left = self.parse_pipe()
        while self.consume(','):
            right = self.parse_pipe()
            left = {"type": "comma", "left": left, "right": right}
        return left

    def parse_pipe(self):
        left = self.parse_term()
        while self.consume('|'):
            right = self.parse_term()
            left = {"type": "pipe", "left": left, "right": right}
        return left

    def parse_term(self):
        t = self.peek()
        if t == '.':
            self.consume('.')
            nxt = self.peek()
            if nxt and re.match(r'[a-zA-Z_]', nxt) and nxt not in ('true', 'false', 'null'):
                field = self.consume()
                base = {"type": "field", "field": field}
            elif nxt == '"':
                self.consume()
                base = {"type": "identity"} # simplify
            elif nxt == '[':
                self.consume('[')
                if self.peek() == ']':
                    self.consume(']')
                    base = {"type": "iterator"}
                else:
                    idx = self.parse_expr()
                    self.consume(']')
                    base = {"type": "index", "index": idx}
            else:
                base = {"type": "identity"}

            while True:
                nxt = self.peek()
                if nxt == '.':
                    self.consume('.')
                    nnxt = self.peek()
                    if nnxt and re.match(r'[a-zA-Z_]', nnxt):
                        f = self.consume()
                        base = {"type": "pipe", "left": base, "right": {"type": "field", "field": f}}
                    else:
                        break
                elif nxt == '[':
                    self.consume('[')
                    if self.peek() == ']':
                        self.consume(']')
                        base = {"type": "pipe", "left": base, "right": {"type": "iterator"}}
                    else:
                        idx = self.parse_expr()
                        self.consume(']')
                        base = {"type": "pipe", "left": base, "right": {"type": "index", "index": idx}}
                else:
                    break
            return base

        elif t and t.startswith('$'):
            var = self.consume()
            return {"type": "variable", "name": var[1:]}
        elif t and re.match(r'[a-zA-Z_]', t) and t not in ('true', 'false', 'null'):
            func = self.consume()
            if func == 'map':
                self.consume('(')
                expr = self.parse_expr()
                self.consume(')')
                return {"type": "map", "expr": expr}
            elif func == 'select':
                self.consume('(')
                expr = self.parse_expr()
                self.consume(')')
                return {"type": "select", "expr": expr}
            elif func == 'keys':
                return {"type": "keys"}
            elif func == 'length':
                return {"type": "length"}
            else:
                return {"type": "func", "name": func}
        elif t == '[':
            self.consume('[')
            if self.peek() == ']':
                self.consume(']')
                return {"type": "array", "expr": None}
            expr = self.parse_expr()
            self.consume(']')
            return {"type": "array", "expr": expr}
        elif t == '(':
            self.consume('(')
            expr = self.parse_expr()
            self.consume(')')
            return expr
        elif t in ('true', 'false', 'null'):
            val = self.consume()
            return {"type": "literal", "value": val}
        else:
            val = self.consume()
            return {"type": "literal", "value": val}

def compile_ast(ast, variables):
    if not ast: return lambda x: [x]

    t = ast["type"]
    if t == "identity":
        return lambda x: [x]
    elif t == "field":
        field = ast["field"]
        return lambda x: [x.get(field)] if isinstance(x, dict) else [None]
    elif t == "pipe":
        left = compile_ast(ast["left"], variables)
        right = compile_ast(ast["right"], variables)
        return lambda x: [y for l in left(x) for y in right(l)]
    elif t == "comma":
        left = compile_ast(ast["left"], variables)
        right = compile_ast(ast["right"], variables)
        return lambda x: left(x) + right(x)
    elif t == "iterator":
        return lambda x: list(x.values()) if isinstance(x, dict) else list(x) if isinstance(x, list) else []
    elif t == "index":
        idx_ast = ast["index"]
        if idx_ast["type"] == "literal":
            val = idx_ast["value"]
            if val.startswith('"'):
                key = val.strip('"')
                return lambda x: [x.get(key)] if isinstance(x, dict) else [None]
            elif re.match(r'-?\d+', val):
                i = int(val)
                return lambda x: [x[i]] if isinstance(x, list) and -len(x) <= i < len(x) else [None]
        return lambda x: [None]
    elif t == "map":
        expr = compile_ast(ast["expr"], variables)
        return lambda x: [[y for item in x for y in expr(item)]] if isinstance(x, list) else [None]
    elif t == "select":
        expr = compile_ast(ast["expr"], variables)
        return lambda x: [x] if any(expr(x)) else []
    elif t == "keys":
        return lambda x: [sorted(list(x.keys()))] if isinstance(x, dict) else [[i for i in range(len(x))]] if isinstance(x, list) else [None]
    elif t == "length":
        return lambda x: [len(x)] if isinstance(x, (dict, list, str)) else [None]
    elif t == "array":
        if ast["expr"] is None:
            return lambda x: [[]]
        expr = compile_ast(ast["expr"], variables)
        return lambda x: [list(expr(x))]
    elif t == "variable":
        name = ast["name"]
        val = variables.get(name)
        return lambda x: [val]
    elif t == "literal":
        v = ast["value"]
        if v == 'true': return lambda x: [True]
        if v == 'false': return lambda x: [False]
        if v == 'null': return lambda x: [None]
        if v.startswith('"'): return lambda x: [v.strip('"')]
        if re.match(r'-?\d+', v): return lambda x: [int(v)] if '.' not in v else [float(v)]
        return lambda x: [v]
    else:
        return lambda x: [None]

def evaluate(expr, data, variables):
    tokens = tokenize(expr)
    parser = Parser(tokens)
    ast = parser.parse()
    compiled = compile_ast(ast, variables)
    return compiled(data)

def main():
    args = sys.argv[1:]
    raw_output = False
    compact = False
    slurp = False
    null_input = False
    raw_input = False
    variables = {}
    expr = None
    files = []

    idx = 0
    while idx < len(args):
        a = args[idx]
        if a in ('-r', '--raw-output'):
            raw_output = True
        elif a in ('-c', '--compact-output'):
            compact = True
        elif a in ('-s', '--slurp'):
            slurp = True
        elif a in ('-n', '--null-input'):
            null_input = True
        elif a in ('-R', '--raw-input'):
            raw_input = True
        elif a == '--arg':
            variables[args[idx+1]] = args[idx+2]
            idx += 2
        elif a == '--argjson':
            variables[args[idx+1]] = json.loads(args[idx+2])
            idx += 2
        elif a in ('-h', '--help'):
            print("jq - commandline JSON processor")
            return
        elif a in ('-V', '--version'):
            print("jq-build-2b77eb1")
            return
        elif a.startswith('-') and a != '-':
            pass # ignore other flags
        else:
            if expr is None:
                expr = a
            else:
                files.append(a)
        idx += 1

    if expr is None:
        expr = "."

    inputs = []

    # Read inputs
    def read_stream(f):
        if raw_input:
            if slurp:
                return [f.read()]
            else:
                return [line.strip("\n") for line in f]

        data = f.read()
        if not data.strip():
            return []

        if slurp:
            decoder = json.JSONDecoder()
            pos = 0
            res = []
            while pos < len(data):
                data = data[pos:].lstrip()
                if not data: break
                try:
                    obj, idx = decoder.raw_decode(data)
                    res.append(obj)
                    pos = idx
                except:
                    break
            return [res]
        else:
            decoder = json.JSONDecoder()
            pos = 0
            res = []
            while pos < len(data):
                data = data[pos:].lstrip()
                if not data: break
                try:
                    obj, idx = decoder.raw_decode(data)
                    res.append(obj)
                    pos = idx
                except:
                    break
            return res

    if null_input:
        inputs = [None]
    else:
        if not files:
            inputs.extend(read_stream(sys.stdin))
        else:
            for fname in files:
                with open(fname, 'r') as f:
                    inputs.extend(read_stream(f))

    for i in inputs:
        try:
            res = evaluate(expr, i, variables)
        except Exception as e:
            print(f"jq: error: {e}", file=sys.stderr)
            continue

        for r in res:
            if raw_output and isinstance(r, str):
                print(r)
            else:
                if compact:
                    print(json.dumps(r, separators=(',', ':')))
                else:
                    print(json.dumps(r, indent=2))

if __name__ == "__main__":
    main()
